import re

file_path = 'docs/architecture/ARCHITECTURE-th.md'
with open(file_path, 'r', encoding='utf-8') as f:
    content = f.read()

replacements = [
    (
        "| กรอบงบสัดส่วนโควต้าการเบิกการคิวสืบ (ในเชิงมิติแบบโครงสร้าง)                             | `tests/lint/query-budget-linter.js`                                                                                                                       | การประทับตีกฎห้ามหน้าจอแผงสแกนบุกพุ่งตะลุยลงช่องแถวแสกนสายวิ่งรันของพิกัดตระเวนแสกนหน้าตาราง `ldi_data` แบบล้วงค่าเพียว ๆ ดิบ ๆ ของมันดื้อๆ ไปทดแทนสวมรันเพื่ออ้างคิวรันจับของกรอบทิศกั้นขีดระบุรอบพิกัดของชั้นคลาสระดับเส้นจุดระบบสาย CAGG อย่างการรันชุดคลาสของตัว `_1m`/`_15m`/`_1h` เอาไปไม่ได้เลยชัวร์ ๆ                                                                                                                                                                                                                                                                                                                                                                                                                                 |",
        "| การจัดการ Query Budget (ในเชิงมิติแบบโครงสร้าง)                                         | `tests/lint/query-budget-linter.js`                                                                                                                       | ตรวจสอบและป้องกันไม่ให้แดชบอร์ดคิวรีข้อมูลดิบจากตาราง `ldi_data` โดยตรง ซึ่งบังคับให้ต้องใช้งานผ่าน Continuous Aggregates (CAGG) เช่น `_1m`, `_15m`, หรือ `_1h` เพื่อบริหารจัดการทรัพยากรฐานข้อมูลอย่างเหมาะสม                                                                                                                                                                                                                                                                                                                                                                                                                                 |"
    ),
    (
        "| ตรวจสอบโครงสร้างข้อมูลที่ไม่มีการอ้างอิงถึง (Orphan Object)                                 | `tests/lint/orphan-object-linter.js`                                                                                                                      | ตัวหน้าบรรทัดกระดานรับตารางเก็บฐานของทุกระบบสดร่วมรวมโหมดทั้งโครงหน้าโครงทอดตัวในวิวมอง จะตกไปเป็นฐานโหมดอยู่ในห้วงโซ่ล๊อคโดนคีบอ้างจับพันพ่วงโยงเชื่อมยึดกับตัวใช้งานให้เอาไปจ่อถูกผูกรั้งประทับอ้างกับแผงจอแดชบอร์ด กองกฏการแจกจุดระบุกฎเงื่อนไขเรียกตั้งสัญญาณกติกาข้อเตือน หรือไม่ว่าถูกเกี่ยวแฝงลากเข้าจังหวะเส้นพุ่งโพรลด์ตัวก๊อกทิศโฟลว์กระแสวิ่ง ก็หรือไม่เว้นโดนจับตีทิ้งประทับให้เป็นรันของสายเส้นตัวโครงระบบไมเกรชันก็ตามแต่ใจสั่งมา อย่างรันยอดจุดรับคือประทับนับจังหวะมีเอี่ยวสักเป็นอันติดคิวเกี่ยวพันพ่วงมาไปละอันนึงละ — ล้างความเนียนร่องรอยการเคว้งโผล่ซ่อนตัวเงียบสถิตหลุดหายล่องลอยแบบไม่ใช้งานไม่เกี่ยวปะติดพ่วงร้อยเข้าข่ายโดนระบบสับสกัดรันอ้างถึงตัวรับรันจริงจังให้จับทำงานที่พิกัดไหนได้เงียบเลยตามเลยเอาดื้อๆชัวร์ |",
        "| ตรวจสอบโครงสร้างข้อมูลที่ไม่มีการอ้างอิงถึง (Orphan Object)                                 | `tests/lint/orphan-object-linter.js`                                                                                                                      | ตรวจสอบว่าตารางข้อมูลและ views ทั้งหมดที่สร้างขึ้น ถูกนำไปใช้งานจริงบนแดชบอร์ด, กฎการแจ้งเตือน, โฟลว์การประมวลผลข้อมูล, หรือระบบไมเกรชันอย่างน้อยหนึ่งแห่ง เพื่อป้องกันการเกิดออบเจกต์ขยะ (Orphan Objects) ในระบบฐานข้อมูลที่ไม่ถูกเรียกใช้งานเลย |"
    )
]

for old_text, new_text in replacements:
    if old_text in content:
        content = content.replace(old_text, new_text)
    else:
        print(f"Warning: Could not find exact match.")

with open(file_path, 'w', encoding='utf-8') as f:
    f.write(content)
print("Updated ARCHITECTURE-th.md part 4")
